const PLAYER_IMAGE_ALIASES: Record<string, string> = {
  "araujo": "araujo",
  "ayoze": "ayoze perez",
  "balde": "alex balde",
  "cancelo": "joao cancelo",
  "cubarsi": "pau cubarsi",
  "gaya": "gaya",
  "kounde": "kounde",
  "thierry": "thierry correia",
  "vinicius": "vinicius jr",
  "williams": "nico williams",
}

export function normalizePlayerName(value: string): string {
  return value
    .toLowerCase()
    .replace(/ø/g, "o")
    .replace(/đ/g, "d")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
}

export function getAnaliticaFantasyPlayerImage(name: string): string | undefined {
  const normalizedName = normalizePlayerName(name)
  const alias = PLAYER_IMAGE_ALIASES[normalizedName]

  return (
    PLAYER_IMAGES_BY_NORMALIZED_NAME[normalizedName] ??
    (alias ? PLAYER_IMAGES_BY_NORMALIZED_NAME[alias] : undefined)
  )
}

export function resolvePlayerImage(name: string, currentImage?: string): string {
  const externalImage = getAnaliticaFantasyPlayerImage(name)

  if (externalImage) return externalImage
  return currentImage ?? ""
}
